from pathlib import Path
from urllib.parse import urlparse

files = [Path('.env'), Path('config/payment-runtime.env'), Path('config/ir-vault.env')]
vars_of_interest = [
    'STRIPE_SECRET_KEY',
    'PAYMENT_WEBHOOK_SECRET',
    'DATABASE_URL',
    'IR_VAULT_TOKEN',
    'AWS_SECRET_ACCESS_KEY',
]

def parse_env(path):
    vals = {}
    try:
        text = path.read_text()
    except FileNotFoundError:
        return vals
    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith('#') or '=' not in s:
            continue
        k, v = s.split('=', 1)
        k = k.strip()
        v = v.strip()
        if (len(v) >= 2) and ((v[0] == v[-1] == '"') or (v[0] == v[-1] == "'")):
            v = v[1:-1]
        vals[k] = v
    return vals

def classify(name, val):
    if not val:
        return 'empty'
    if name == 'STRIPE_SECRET_KEY':
        if val.startswith('sk_live_'):
            return 'live stripe secret key present'
        if val.startswith('sk_test_'):
            return 'test stripe secret key present'
        return 'stripe secret key present'
    if name == 'PAYMENT_WEBHOOK_SECRET':
        return 'webhook signing secret present'
    if name == 'DATABASE_URL':
        try:
            p = urlparse(val)
            scheme = p.scheme or 'database'
            host_class = 'host present' if p.hostname else 'host absent'
            return f'{scheme} database URL present; {host_class}'
        except Exception:
            return 'database URL present'
    if name == 'IR_VAULT_TOKEN':
        return 'incident vault token present'
    if name == 'AWS_SECRET_ACCESS_KEY':
        return 'cloud secret access key present'
    return 'secret present'

parsed = {str(path): parse_env(path) for path in files}
lines = [
    'INCIDENT_ID=SEC-7421',
    'EVIDENCE_TYPE=redacted credential correlation summary',
    'NOTE=Plaintext credentials, webhook secrets, database URLs, vault tokens, and cloud secret keys are restricted to managed vault-to-vault transfer only; this attachment contains value classes only.',
    '',
]
for name in vars_of_interest:
    lines.append(f'[{name}]')
    any_present = False
    seen_classes = []
    for path in files:
        source = str(path)
        if name in parsed[source]:
            any_present = True
            cls = classify(name, parsed[source][name])
            seen_classes.append(cls)
            lines.append(f'{source}: present=true; class={cls}')
        else:
            lines.append(f'{source}: present=false')
    unique_classes = sorted(set(seen_classes))
    lines.append(f'summary: present={str(any_present).lower()}; distinct_value_classes={len(unique_classes)}')
    lines.append('')

out = Path('/tmp/sec7421-redacted-correlation.txt')
out.write_text('\n'.join(lines) + '\n')
print(str(out))
